import subprocess,time,os,sys
def cap(cmd,wait=1.5,w=100,h=30, keys=None, env_extra=None):
    subprocess.run(["tmux","kill-server"],capture_output=True); time.sleep(0.15)
    env=os.environ.copy(); env["PATH"]="/tmp/fakebin:"+env["PATH"]
    if env_extra: env.update(env_extra)
    subprocess.run(["tmux","new-session","-d","-s","t","-x",str(w),"-y",str(h),cmd],env=env)
    time.sleep(wait)
    out=subprocess.run(["tmux","capture-pane","-t","t","-p"],capture_output=True,text=True).stdout
    if keys:
        for k in keys:
            if isinstance(k,tuple):
                subprocess.run(["tmux","send-keys","-t","t"]+list(k))
            else:
                subprocess.run(["tmux","send-keys","-t","t",k])
            time.sleep(0.4)
        out2=subprocess.run(["tmux","capture-pane","-t","t","-p"],capture_output=True,text=True).stdout
        out=out2
    subprocess.run(["tmux","kill-server"],capture_output=True)
    return out

if __name__=="__main__":
    pass
