    thread,
    time::Duration,
};

#[derive(Debug, Clone, Copy)]
pub enum PingResult {
    Success(Duration),
    Timeout,
}

#[derive(Debug)]
pub enum PingEvent {
    Result(PingResult),
    Done { status: ExitStatus, stderr: String },
}

fn parse_timeout(line: &str) -> bool {
    line.starts_with("no answer yet")
}

fn parse_success(line: &str) -> Option<Duration> {
    if !line.starts_with("64 bytes from") {
        return None;
    }

    let lower = line.to_ascii_lowercase();
    let mut search_from = 0usize;
    while let Some(found) = lower[search_from..].find("time=") {
        let time_start = search_from + found;
        let value_start = time_start + "time=".len();
        if let Some(duration) = parse_time_at(line, value_start) {
            return Some(duration);
        }
        search_from = time_start + 1;
    }
    None
}

fn parse_time_at(line: &str, start: usize) -> Option<Duration> {
    let bytes = line.as_bytes();
    let mut pos = start;

    let integer_start = pos;
    while pos < bytes.len() && bytes[pos].is_ascii_digit() {
        pos += 1;
    }
    if integer_start == pos {
        return None;
    }
    let integer_part = &line[integer_start..pos];
    // Values that do not fit in a u64 are ignored, matching the observable
    // behavior for extremely large synthetic ping output.
    integer_part.parse::<u64>().ok()?;

    let mut fraction_part = "";
    if pos < bytes.len() && bytes[pos] == b'.' {
        let fraction_start = pos + 1;
        let mut fraction_end = fraction_start;
        while fraction_end < bytes.len() && bytes[fraction_end].is_ascii_digit() {
            fraction_end += 1;
        }
        if fraction_end == fraction_start {
            return None;
        }
        fraction_part = &line[fraction_start..fraction_end];
        pos = fraction_end;
    }

    while pos < bytes.len() && bytes[pos] == b' ' {
        pos += 1;
    }
    if pos + 1 >= bytes.len()
        || !bytes[pos].eq_ignore_ascii_case(&b'm')
        || !bytes[pos + 1].eq_ignore_ascii_case(&b's')
    {
        return None;
    }

    // Ping implementations normally print at most three fractional digits.
    // The reference parser keeps fractional parts up to six digits (truncating
    // them to microsecond resolution) and disregards longer fractions.
    let value = if fraction_part.len() > 6 {
        integer_part.parse::<f64>().ok()?
    } else if fraction_part.is_empty() {
        integer_part.parse::<f64>().ok()?
    } else {
        format!("{integer_part}.{fraction_part}")
            .parse::<f64>()
            .ok()?
    };
    Some(Duration::from_micros((value * 1000.0) as u64))
}

