/// Start a ping process for `target` and return a channel of results.
///
/// The final event on the channel reports how the ping process ended,
/// together with everything it wrote to stderr.
pub fn ping(
    target: &str,
    interval: Duration,
    interface: Option<&str>,
    use_ipv6: bool,
    extra_args: &[String],
) -> Result<Receiver<PingEvent>> {
