    let args = kind.command_args(target, interval, interface, extra_args);
    let binary = if use_ipv6 { "ping6" } else { "ping" };

    let mut child = Command::new(binary)
        .args(&args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(linux::spawn_error)?;
    let stdout = child.stdout.take().expect("ping stdout was piped");
    let stderr = child.stderr.take().expect("ping stderr was piped");

    let (sender, receiver) = mpsc::channel();
    let result_sender = sender.clone();
    let stdout_thread = thread::spawn(move || {
        let reader = BufReader::new(stdout);
        for line in reader.lines() {
            let Ok(line) = line else {
                break;
            };
            if let Some(result) = parse_line(&line) {
                if result_sender.send(PingEvent::Result(result)).is_err() {
                    break;
                }
            }
        }
    });

    let stderr_thread = thread::spawn(move || {
        let mut stderr_reader = stderr;
        let mut bytes = Vec::new();
        let _ = stderr_reader.read_to_end(&mut bytes);
        String::from_utf8(bytes).expect("Error decoding stderr")
    });

    thread::spawn(move || {
        let Ok(status) = child.wait() else {
            return;
        };
        let Ok(stderr) = stderr_thread.join() else {
            return;
        };
        let _ = stdout_thread.join();
        let _ = sender.send(PingEvent::Done { status, stderr });
    });

    Ok(receiver)
}
