#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum IpVersion {
    V4,
    V6,
}

impl IpVersion {
    fn name(self) -> &'static str {
        match self {
            Self::V4 => "IPv4",
            Self::V6 => "IPv6",
        }
    }
}

#[derive(Debug)]
struct Target {
    display: String,
    source: String,
    ping_target: String,
    use_ipv6_for_ping: bool,
    color: Color,
}

fn expand_cloud_shorthand(host: &str) -> String {
    if let Some(region) = host.strip_prefix("aws:") {
        format!("ec2.{region}.amazonaws.com")
    } else if let Some(region) = host.strip_prefix("gcp:") {
        format!("storage.{region}.rep.googleapis.com")
    } else {
        host.to_owned()
    }
}

fn resolve_ping_target(
    host: &str,
    requested_version: Option<IpVersion>,
) -> Result<(IpAddr, String, bool)> {
    if let Ok(ip) = host.parse::<IpAddr>() {
        if let Some(version) = requested_version {
            let matches = match version {
                IpVersion::V4 => ip.is_ipv4(),
                IpVersion::V6 => ip.is_ipv6(),
            };
            if !matches {
                bail!("Could not resolve '{host}' to {}", version.name());
            }
        }
        let use_ipv6 = ip.is_ipv6();
        return Ok((ip, ip.to_string(), use_ipv6));
    }

    let addresses: Vec<_> = (host, 0)
        .to_socket_addrs()
        .with_context(|| format!("Resolving {host}"))?
        .collect();
    let selected = match requested_version {
        None => addresses.first(),
        Some(IpVersion::V4) => addresses.iter().find(|address| address.is_ipv4()),
        Some(IpVersion::V6) => addresses.iter().find(|address| address.is_ipv6()),
    };
    let Some(selected) = selected else {
        match requested_version {
            Some(version) => bail!("Could not resolve '{host}' to {}", version.name()),
            None => bail!("Could not resolve '{host}'"),
        }
    };

    Ok((
        selected.ip(),
        host.to_owned(),
        requested_version == Some(IpVersion::V6),
    ))
}

fn parse_color(raw: &str) -> Result<Color> {
    Color::from_str(raw)
        .map_err(|_| anyhow!("Failed to parse Colors"))
        .with_context(|| format!("Invalid color code: `{raw}`"))
}

fn build_targets(args: &Args) -> Result<Vec<Target>> {
    let split_colors: Vec<&str> = args
        .colors
        .iter()
        .flat_map(|color| color.split(','))
        .collect();
    let requested_version = if args.use_ipv4 {
        Some(IpVersion::V4)
    } else if args.use_ipv6 {
        Some(IpVersion::V6)
    } else {
        None
    };

    let mut targets = Vec::with_capacity(args.hosts_or_commands.len());
    for (index, original) in args.hosts_or_commands.iter().enumerate() {
        let color = if let Some(raw_color) = split_colors.get(index) {
            parse_color(raw_color)?
        } else {
            Color::Indexed((index - split_colors.len() + 2) as u8)
        };

        if args.cmd {
            targets.push(Target {
                display: original.clone(),
                source: original.clone(),
                ping_target: String::new(),
                use_ipv6_for_ping: false,
                color,
            });
        } else {
            let host = expand_cloud_shorthand(original);
            let (ip, ping_target, use_ipv6_for_ping) =
                resolve_ping_target(&host, requested_version)?;
            targets.push(Target {
                display: format!("{host} ({ip})"),
                source: original.clone(),
                ping_target,
                use_ipv6_for_ping,
                color,
            });
        }
    }
    Ok(targets)
}

fn split_command(command: &str) -> (String, Vec<String>) {
    let mut parts = command.split_whitespace();
    let program = parts
        .next()
        .expect("Must specify a command to watch")
        .to_owned();
    let arguments = parts.map(|part| part.to_owned()).collect();
    (program, arguments)
}

#[derive(Debug, Clone, Copy)]
struct DataPoint {
    x: f64,
    duration: Option<Duration>,
}

#[derive(Debug)]
struct Series {
    display: String,
    color: Color,
    points: VecDeque<DataPoint>,
}

impl Series {
    fn new(display: String, color: Color) -> Self {
        Self {
            display,
            color,
            points: VecDeque::new(),
        }
    }

    fn add(&mut self, point: DataPoint, buffer: f64) {
        self.points.push_back(point);
        let cutoff = point.x - buffer;
        while self.points.len() > 1 {
            let Some(second) = self.points.get(1) else {
                break;
            };
            if second.x < cutoff {
                self.points.pop_front();
            } else {
                break;
            }
        }
    }

    fn successful_durations(&self) -> Vec<Duration> {
        self.points
            .iter()
            .filter_map(|point| point.duration)
            .collect()
    }
}

#[derive(Debug)]
struct GraphStats {
    last: Duration,
    min: Duration,
    max: Duration,
    avg: Duration,
    jitter: Duration,
    p95: Duration,
    timeouts: usize,
}

fn duration_from_average_micros(value: f64) -> Duration {
    if !value.is_finite() || value <= 0.0 {
        Duration::ZERO
    } else {
        Duration::from_micros(value as u64)
    }
}

fn calculate_stats(series: &Series) -> Option<GraphStats> {
    let mut durations = series.successful_durations();
    if durations.is_empty() {
        return None;
    }

    let last = series
        .points
        .back()
        .and_then(|point| point.duration)
        .unwrap_or_default();
    durations.sort_unstable();

    let min = *durations.first().unwrap_or(&Duration::ZERO);
    let max = *durations.last().unwrap_or(&Duration::ZERO);
    let average_micros = durations
        .iter()
        .map(|duration| duration.as_micros() as f64)
        .sum::<f64>()
        / durations.len() as f64;
    let jitter = if durations.len() > 1 {
        let total_difference: f64 = durations
            .windows(2)
            .map(|pair| pair[1].as_micros() as f64 - pair[0].as_micros() as f64)
            .sum();
        duration_from_average_micros(total_difference / (durations.len() - 1) as f64)
    } else {
        Duration::ZERO
    };
    let p95_index = (durations.len() as f64 * 0.95).round() as usize;
    let p95 = durations.get(p95_index).copied().unwrap_or_default();
    let timeouts = series
        .points
        .iter()
        .filter(|point| point.duration.is_none())
        .count();

    Some(GraphStats {
        last: duration_from_average_micros(last.as_micros() as f64),
        min: duration_from_average_micros(min.as_micros() as f64),
        max: duration_from_average_micros(max.as_micros() as f64),
        avg: duration_from_average_micros(average_micros),
        jitter,
        p95: duration_from_average_micros(p95.as_micros() as f64),
        timeouts,
    })
}

#[derive(Debug)]
enum AppEvent {
    Terminal(TerminalEvent),
    Sample(usize, Option<Duration>),
    PingFinished(ExitStatus, String),
}

#[derive(Debug)]
struct App {
    series: Vec<Series>,
    start: Instant,
    start_time: NaiveTime,
    buffer_seconds: u64,
}

impl App {
    fn new(targets: &[Target], buffer_seconds: u64) -> Self {
        let start_time = Local::now()
            .time()
            .with_nanosecond(0)
            .unwrap_or_else(|| Local::now().time());
        Self {
            series: targets
                .iter()
                .map(|target| Series::new(target.display.clone(), target.color))
                .collect(),
            start: Instant::now(),
            start_time,
            buffer_seconds,
        }
    }

    fn add_sample(&mut self, index: usize, duration: Option<Duration>) {
        let x = self.start.elapsed().as_secs_f64();
        if let Some(series) = self.series.get_mut(index) {
            series.add(
                DataPoint { x, duration },
                self.buffer_seconds as f64,
            );
        }
    }

    fn x_bounds(&self) -> (f64, f64) {
        let buffer = self.buffer_seconds as f64;
        let elapsed = self.start.elapsed().as_secs();
        let max = if elapsed > self.buffer_seconds {
            elapsed as f64
        } else {
            buffer
        };
        (max - buffer, max)
    }

    fn x_labels(&self) -> Vec<Line<'static>> {
        let (min, max) = self.x_bounds();
        [min, (min + max) / 2.0, max]
            .into_iter()
            .map(|seconds| {
                let label_time = self
                    .start_time
                    .overflowing_add_signed(TimeDelta::from_secs_f64(seconds))
                    .0;
                Line::from(format!("{label_time}"))
            })
            .collect()
    }
}

fn spawn_terminal_event_thread(sender: Sender<AppEvent>) {
    thread::spawn(move || loop {
        match crossterm::event::read() {
            Ok(event) => {
                if sender.send(AppEvent::Terminal(event)).is_err() {
                    break;
                }
            }
            Err(_) => break,
        }
    });
}

fn spawn_command(
    index: usize,
    command: &str,
    interval: Duration,
    sender: Sender<AppEvent>,
) {
    let (program, arguments) = split_command(command);
    thread::spawn(move || loop {
        let started = Instant::now();
        let status = Command::new(&program)
            .args(&arguments)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
        let elapsed = started.elapsed();
        let sample = match status {
            Ok(status) if status.success() => Some(elapsed),
            _ => None,
        };
        if sender.send(AppEvent::Sample(index, sample)).is_err() {
            break;
        }
        thread::sleep(interval);
    });
}

fn spawn_pinger(
    index: usize,
    target: &Target,
    interval: Duration,
    interface: Option<&str>,
    ping_args: &[String],
    sender: Sender<AppEvent>,
) -> Result<()> {
    let receiver: Receiver<PingEvent> = pinger::ping(
        &target.ping_target,
        interval,
        interface,
        target.use_ipv6_for_ping,
        ping_args,
    )?;

    thread::spawn(move || {
        while let Ok(event) = receiver.recv() {
            let app_event = match event {
                PingEvent::Result(PingResult::Success(duration)) => {
                    AppEvent::Sample(index, Some(duration))
                }
                PingEvent::Result(PingResult::Timeout) => AppEvent::Sample(index, None),
                PingEvent::Done { status, stderr } => AppEvent::PingFinished(status, stderr),
            };
            if sender.send(app_event).is_err() {
                break;
            }
        }
    });
    Ok(())
}

fn should_quit(key: &KeyEvent) -> bool {
    key.code == KeyCode::Esc
        || key.code == KeyCode::Char('q')
        || (key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL))
}

fn duration_label(value_micros: f64) -> String {
    format!("{:?}", duration_from_average_micros(value_micros))
}

fn draw(frame: &mut ratatui::Frame<'_>, app: &App, args: &Args) {
    let outer = Layout::vertical([
        Constraint::Length(app.series.len() as u16),
        Constraint::Min(0),
    ])
    .vertical_margin(args.vertical_margin)
    .horizontal_margin(args.horizontal_margin);
    let [header_area, chart_area] = outer.areas(frame.area());

    let header_rows = Layout::vertical(
        app.series
            .iter()
            .map(|_| Constraint::Length(1))
            .collect::<Vec<_>>(),
    )
    .split(header_area);

    for (series, row) in app.series.iter().zip(header_rows.iter()) {
        let columns = Layout::horizontal([
            Constraint::Percentage(30),
            Constraint::Percentage(10),
            Constraint::Percentage(10),
            Constraint::Percentage(10),
            Constraint::Percentage(10),
            Constraint::Percentage(10),
            Constraint::Percentage(10),
            Constraint::Percentage(10),
        ])
        .split(*row);
        let style = Style::default().fg(series.color);

        frame.render_widget(
            Paragraph::new(series.display.clone()).style(style),
            columns[0],
        );
        if let Some(stats) = calculate_stats(series) {
            let labels = [
                format!("last {:?}", stats.last),
                format!("min {:?}", stats.min),
                format!("max {:?}", stats.max),
                format!("avg {:?}", stats.avg),
                format!("jtr {:?}", stats.jitter),
                format!("p95 {:?}", stats.p95),
                format!("t/o {}", stats.timeouts),
            ];
            for (label, column) in labels.into_iter().zip(columns.iter().skip(1)) {
                frame.render_widget(Paragraph::new(label).style(style), *column);
            }
        }
    }

    let all_durations: Vec<f64> = app
        .series
        .iter()
        .flat_map(|series| series.successful_durations())
        .map(|duration| duration.as_micros() as f64)
        .collect();
    let min_y = all_durations.iter().copied().fold(f64::INFINITY, f64::min);
    let max_y = all_durations
        .iter()
        .copied()
        .fold(f64::NEG_INFINITY, f64::max);
    let has_durations = !all_durations.is_empty();
    let (label_min_y, label_max_y) = if has_durations {
        (min_y * 0.9, max_y * 1.1)
    } else {
        (0.0, 0.0)
    };
    let y_bounds = if has_durations {
        [label_min_y, label_max_y]
    } else {
        [0.0, 1.0]
    };
    let y_labels: Vec<Line<'static>> = (0..7)
        .map(|index| {
            let value = label_min_y + index as f64 * (label_max_y - label_min_y) / 7.0;
            Line::from(duration_label(value))
        })
        .collect();

    let datasets: Vec<(Vec<(f64, f64)>, Color)> = app
        .series
        .iter()
        .map(|series| {
            let points = series
                .points
                .iter()
                .map(|point| {
                    let y = point
                        .duration
                        .map(|duration| duration.as_micros() as f64)
                        .unwrap_or(y_bounds[1]);
                    (point.x, y)
                })
                .collect::<Vec<_>>();
            (points, series.color)
        })
        .collect();
    let marker = if args.simple_graphics {
        Marker::Dot
    } else {
        Marker::Braille
    };
    let ratatui_datasets: Vec<Dataset<'_>> = datasets
        .iter()
        .map(|(points, color)| {
            Dataset::default()
                .marker(marker)
                .graph_type(GraphType::Line)
                .style(Style::default().fg(*color))
                .data(points)
        })
        .collect();

    let (min_x, max_x) = app.x_bounds();
    let axis_style = Style::default().fg(Color::Gray);
    let chart = Chart::new(ratatui_datasets)
        .x_axis(
            Axis::default()
                .style(axis_style)
                .bounds([min_x, max_x])
                .labels(app.x_labels()),
        )
        .y_axis(
            Axis::default()
                .style(axis_style)
                .bounds(y_bounds)
                .labels(y_labels),
        );
    frame.render_widget(chart, chart_area);
}

fn run(args: Args) -> Result<()> {
    if args.hosts_or_commands.is_empty() {
        bail!(
            "At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments."
        );
    }

    let targets = build_targets(&args)?;
    let default_interval = if args.cmd { 0.5 } else { 0.2 };
    let interval_seconds = args.watch_interval.unwrap_or(default_interval);
    let watch_interval = Duration::from_millis((interval_seconds * 1000.0) as u64);

    let (sender, receiver) = mpsc::channel::<AppEvent>();
    let mut app = App::new(&targets, args.buffer);

    for (index, target) in targets.iter().enumerate() {
        if args.cmd {
            spawn_command(index, &target.source, watch_interval, sender.clone());
        } else {
            spawn_pinger(
                index,
                target,
                watch_interval,
                args.interface.as_deref(),
                &args.ping_args,
                sender.clone(),
            )?;
        }
    }

    enable_raw_mode()?;

    let mut stdout: Stdout = io::stdout();
    let terminal_result = (|| -> Result<()> {
        if let Ok((width, height)) = crossterm::terminal::size() {
            let _ = execute!(stdout, SetSize(width, height));
        }
        if args.clear {
            execute!(stdout, EnterAlternateScreen)?;
        }
        execute!(stdout, Clear(ClearType::All))?;

        let backend = CrosstermBackend::new(stdout);
        let mut terminal = Terminal::new(backend)?;
        spawn_terminal_event_thread(sender.clone());

        let mut ping_failure: Option<(ExitStatus, String)> = None;
        let mut loop_error: Option<anyhow::Error> = None;
        let tick = Duration::from_millis(250);
        let mut next_tick = Instant::now() + tick;

        'event_loop: loop {
            let now = Instant::now();
            if now >= next_tick {
                if let Err(error) = terminal.draw(|frame| draw(frame, &app, &args)) {
                    loop_error = Some(error.into());
                    break 'event_loop;
                }
                next_tick += tick;
                if next_tick <= now {
                    next_tick = now + tick;
                }
                continue;
            }

            match receiver.recv_timeout(next_tick.saturating_duration_since(now)) {
                Ok(AppEvent::Sample(index, sample)) => {
                    app.add_sample(index, sample);
                }
                Ok(AppEvent::PingFinished(status, stderr)) => {
                    if !status.success() {
                        ping_failure = Some((status, stderr));
                    }
                    break 'event_loop;
                }
                Ok(AppEvent::Terminal(TerminalEvent::Key(key))) => {
                    if should_quit(&key) {
                        break 'event_loop;
                    }
                }
                Ok(AppEvent::Terminal(_)) => {}
                Err(RecvTimeoutError::Timeout) => {}
                Err(RecvTimeoutError::Disconnected) => {
                    // Keeping the original sender in this scope makes this
                    // practically unreachable, but sleeping avoids a busy
                    // loop if all worker threads have unexpectedly ended.
                    thread::sleep(Duration::from_millis(10));
                }
            }
        }

        if let Some((status, stderr)) = ping_failure {
            eprintln!("There was an error running ping: {status}\nStderr: {stderr}\n");
        }

        let terminal_size = terminal.size().unwrap_or(ratatui::layout::Size {
            width: 0,
            height: 0,
        });
        let _ = disable_raw_mode();
        let _ = terminal.show_cursor();
        let _ = execute!(
            terminal.backend_mut(),
            MoveTo(terminal_size.width, terminal_size.height)
        );
        if args.clear {
            let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
        }

        if let Some(error) = loop_error {
            return Err(error);
        }
        Ok(())
    })();

    if terminal_result.is_err() {
        let _ = disable_raw_mode();
    }
    terminal_result
}

fn main() -> Result<()> {
    let args = Args::parse();
    run(args)
}
