#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum IpVersion {
    V4,
    V6,
}

impl IpVersion {
    fn name(self) -> &'static str {
        match self {
            Self::V4 => "IPv4",
            Self::V6 => "IPv6",
        }
    }
}

#[derive(Debug)]
struct Target {
    display: String,
    source: String,
    ping_target: String,
    use_ipv6_for_ping: bool,
    color: Color,
