fn expand_cloud_shorthand(host: &str) -> String {
    if let Some(region) = host.strip_prefix("aws:") {
        format!("ec2.{region}.amazonaws.com")
    } else if let Some(region) = host.strip_prefix("gcp:") {
        format!("storage.{region}.rep.googleapis.com")
    } else {
